local({
  score <- as.numeric(SES_PCAscore_imputed)
  low <- stats::ave(score, wave, FUN = function(v) stats::quantile(v, 0.4, na.rm = TRUE, names = FALSE))
  high <- stats::ave(score, wave, FUN = function(v) stats::quantile(v, 0.6, na.rm = TRUE, names = FALSE))
  case_when(score <= low ~ "Low", score <= high ~ "Medium", score > high ~ "High", .default = "Unknown")
})

local({
  t2 <- c(0, NA, NA, 0.125, 0.375, 0.75, 1.5, 2.5, 3.5, 4)
  t3 <- c(0, 0.125, 0.375, 0.75, 1.5, 2.5, 3.5, 4)
  if_else(
    wave == "T2",
    t2[PC_BabyGames + 1] + t2[CA_BabyGames + 1],
    t3[PC_Time_BabyGames + 1] * PC_Days_BabyGames / 7 + t3[CA_Time_BabyGames + 1] * CA_Days_BabyGames / 7
  )
})
